mapper.select:
SELECT g.common_code_group_id
FROM tb_common_code_group g
WHERE g.tenant_id = #{tenantId}
  AND g.group_code = #{groupCode}
LIMIT 1

mapper.delete:
DELETE FROM tb_common_code_group
WHERE common_code_group_id = #{groupId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(*)
FROM tb_common_code_group
WHERE parent_group_id = #{groupId}
  AND tenant_id = #{tenantId}

SELECT COUNT(*)
FROM tb_common_code_item
WHERE group_id = #{groupId}
  AND tenant_id = #{tenantId}
